import React, { useState, useRef, useEffect } from 'react';
import { attendanceAPI } from './api_service';

const CameraRecognition = ({ addNotification }) => {
  const videoRef = useRef(null);
  const canvasRef = useRef(null);

  const [streaming, setStreaming] = useState(false);
  const [capturedImage, setCapturedImage] = useState(null);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);

  // ================= CAMERA =================
  const startCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: true });
      videoRef.current.srcObject = stream;
      setStreaming(true);
    } catch (err) {
      addNotification('Accès caméra refusé', 'error');
    }
  };

  const stopCamera = () => {
    videoRef.current?.srcObject?.getTracks().forEach(track => track.stop());
    setStreaming(false);
  };

  // ================= CAPTURE =================
  const captureImage = () => {
    const canvas = canvasRef.current;
    const video = videoRef.current;

    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;

    canvas.getContext('2d').drawImage(video, 0, 0);

    const base64 = canvas.toDataURL('image/jpeg');
    setCapturedImage(base64);
    setResult(null);
  };

  // ================= RECOGNITION =================
  const recognizeFace = async () => {
    if (!capturedImage) return;

    setLoading(true);
    setResult(null);

    try {
      const response = await attendanceAPI.recognize(capturedImage);

      if (response.success) {
        setResult({ status: 'success', data: response.data });
      } else if (response.isNoMatch) {
        setResult({ status: 'nomatch' });
      } else {
        throw new Error(response.error);
      }
    } catch (err) {
      setResult({ status: 'error', error: err.message });
    }

    setLoading(false);
  };

  useEffect(() => {
    return () => stopCamera();
  }, []);

  return (
    <div style={styles.page}>

      {/* ================= NAVBAR ================= */}
      <div style={styles.navbar}>
        <div style={styles.logo}>FaceRecognition</div>
        <div style={styles.navLinks}>
          <span style={styles.link}>Accueil</span>
          <span style={styles.link}>Enregistrement</span>
          <span style={styles.link}>Reconnaissance</span>
        </div>
      </div>

      {/* ================= HERO IMAGE ================= */}
      <div style={styles.hero}>
        <img 
          src="https://images.unsplash.com/photo-1581090700227-4c4f50f5a6e2"
          alt="hero"
          style={styles.heroImage}
        />
        <div style={styles.heroOverlay}>
          <h1 style={styles.heroTitle}>Système de reconnaissance faciale intelligent</h1>
          <p style={styles.heroSubtitle}>
            Identification rapide, sécurisée et moderne
          </p>
        </div>
      </div>

      {/* ================= MAIN ================= */}
      <div style={styles.container}>
        <h2 style={styles.sectionTitle}>Reconnaissance en temps réel</h2>

        {/* CAMERA */}
        <div style={styles.card}>
          <video ref={videoRef} autoPlay style={styles.video} />
          <canvas ref={canvasRef} style={{ display: 'none' }} />
        </div>

        {/* CONTROLS */}
        <div style={styles.controls}>
          {!streaming ? (
            <button onClick={startCamera} style={styles.primaryBtn}>Démarrer</button>
          ) : (
            <button onClick={stopCamera} style={styles.dangerBtn}>Arrêter</button>
          )}

          <button onClick={captureImage} disabled={!streaming} style={styles.secondaryBtn}>
            Capturer
          </button>

          <button onClick={recognizeFace} disabled={!capturedImage || loading} style={styles.primaryBtn}>
            {loading ? 'Analyse en cours...' : 'Reconnaître'}
          </button>

          {capturedImage && (
            <button onClick={() => setCapturedImage(null)} style={styles.secondaryBtn}>
              Réinitialiser
            </button>
          )}
        </div>

        {/* PREVIEW */}
        {capturedImage && (
          <div style={styles.previewBox}>
            <img src={capturedImage} style={styles.preview} />
          </div>
        )}

        {/* RESULT */}
        {result && (
          <div style={styles.resultBox}>

            {result.status === 'success' && (
              <div style={styles.successCard}>
                <h3 style={styles.successTitle}>{result.data.student_name}</h3>

                <div style={styles.grid}>
                  <div><strong>Email:</strong> {result.data.email ?? "Non disponible"}</div>
                  <div><strong>Confiance:</strong> {(result.data.confidence * 100).toFixed(1)}%</div>
                  <div>
                    <strong>Heure:</strong> {
                      result.data.timestamp
                        ? new Date(result.data.timestamp.replace(" ", "T")).toLocaleString()
                        : "Non disponible"
                    }
                  </div>
                  <div><strong>ID présence:</strong> {result.data.attendance_id ?? "N/A"}</div>
                  <div><strong>Embedding:</strong> {result.data.embedding_id ?? "N/A"}</div>
                </div>

                {result.data.photo_path && (
                  <img src={result.data.photo_path} style={styles.photo} />
                )}
              </div>
            )}

            {result.status === 'nomatch' && (
              <div style={styles.warningCard}>Aucun visage correspondant</div>
            )}

            {result.status === 'error' && (
              <div style={styles.errorCard}>{result.error}</div>
            )}
          </div>
        )}

      </div>
    </div>
  );
};

// ================= STYLES =================
const styles = {
  page: { fontFamily: 'Arial', background: '#F8FAFC' },

  navbar: {
    display: 'flex',
    justifyContent: 'space-between',
    padding: '20px 40px',
    background: '#111827',
    color: 'white'
  },

  logo: { fontWeight: 'bold', fontSize: 20 },

  navLinks: { display: 'flex', gap: 20 },

  link: { cursor: 'pointer', opacity: 0.8 },

  hero: { position: 'relative', height: 300 },

  heroImage: { width: '100%', height: '100%', objectFit: 'cover' },

  heroOverlay: {
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
    background: 'rgba(0,0,0,0.5)',
    color: 'white',
    display: 'flex',
    flexDirection: 'column',
    justifyContent: 'center',
    alignItems: 'center'
  },

  heroTitle: { fontSize: 32 },
  heroSubtitle: { opacity: 0.8 },

  container: { maxWidth: 900, margin: '40px auto', padding: 20 },

  sectionTitle: { marginBottom: 20 },

  card: {
    borderRadius: 12,
    overflow: 'hidden',
    boxShadow: '0 4px 12px rgba(0,0,0,0.1)'
  },

  video: { width: '100%' },

  controls: {
    display: 'flex',
    gap: 10,
    marginTop: 20,
    flexWrap: 'wrap'
  },

  primaryBtn: {
    background: '#4F46E5',
    color: 'white',
    padding: '10px 20px',
    borderRadius: 8,
    border: 'none'
  },

  secondaryBtn: {
    background: '#E5E7EB',
    padding: '10px 20px',
    borderRadius: 8,
    border: 'none'
  },

  dangerBtn: {
    background: '#EF4444',
    color: 'white',
    padding: '10px 20px',
    borderRadius: 8,
    border: 'none'
  },

  previewBox: { marginTop: 20 },

  preview: { width: '100%', borderRadius: 8 },

  resultBox: { marginTop: 30 },

  successCard: {
    background: '#ECFDF5',
    padding: 20,
    borderRadius: 10
  },

  successTitle: { marginBottom: 10 },

  grid: {
    display: 'grid',
    gridTemplateColumns: '1fr 1fr',
    gap: 10
  },

  photo: { width: 120, marginTop: 10, borderRadius: 8 },

  warningCard: {
    background: '#FEF3C7',
    padding: 20,
    borderRadius: 10
  },

  errorCard: {
    background: '#FEE2E2',
    padding: 20,
    borderRadius: 10
  }
};

export default CameraRecognition;
